<?php
declare(strict_types=1);
/**
 * install_payouts_finish_cleanup_v006_20261105_040000pm.php
 *
 * VERSION: v006
 * LAST MODIFIED: 11/5/2026 4:00:00 pm ET
 *
 * PURPOSE:
 * - Update race_results/payouts.php from installed v005 to presentation/exports v005.
 * - Center a larger OFFICIAL/UNOFFICIAL status banner.
 * - Change weekly payout labels to High Point Total R##.
 * - Change Team Payout totals to Grand Total — Through R##.
 * - Add Excel — Everything and PDF / Print — Everything while preserving Main Chart exports.
 * - Preserve payout calculations, tie allocation, helper/admin/config files, scoring, database, cron/scheduler, email, and picks.
 *
 * INSTALLER LOCATION STANDARD:
 * - Upload/run from /public_html/_installers/.
 * - Backups are stored under /public_html/_installer_backups/.
 *
 * PHP: 7.3 compatible.
 */
date_default_timezone_set('America/New_York');
if(session_status()===PHP_SESSION_NONE) session_start();

$piRoot=dirname(__DIR__);
require_once $piRoot.'/config.php';
require_once $piRoot.'/config_mrl.php';
require_once $piRoot.'/class.user.php';

$user_home=new USER();
if(!$user_home->is_logged_in()){$user_home->redirect('/login.php');exit;}
if(!function_exists('isAdmin')||!isAdmin((int)($_SESSION['userSession']??0))){http_response_code(403);exit('Admin access required.');}

const PI_VER='v006';
const PI_TARGET='race_results/payouts.php';
const PI_OLD_SHA='7390786809a7328a6624e0755ebba9cf60b338e1e702bea6080de3e459e95b7f';
const PI_NEW_SHA='d314ff2f01de93395d2cfd88848641a76f5cd6dece64120076289e6732461b62';
const PI_B64='';

function pih($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function piroot():string{return dirname(__DIR__);}
function pitarget():string{return piroot().'/'.PI_TARGET;}
function pilint(string $f):array{
    if(!function_exists('shell_exec'))return ['ok'=>false,'output'=>'shell_exec unavailable'];
    $o=trim((string)shell_exec('php -l '.escapeshellarg($f).' 2>&1'));
    return ['ok'=>($o!==''&&strpos($o,'No syntax errors detected')!==false),'output'=>$o];
}
function picandidate():array{
    $r=base64_decode(PI_B64,true);
    if(!is_string($r))return ['ok'=>false,'raw'=>'','sha'=>'','lint'=>['ok'=>false,'output'=>'Decode failed.']];
    $s=hash('sha256',$r);
    $tmp=tempnam(sys_get_temp_dir(),'mrlpv5_');
    if(!$tmp)return ['ok'=>false,'raw'=>$r,'sha'=>$s,'lint'=>['ok'=>false,'output'=>'Temp file failed.']];
    file_put_contents($tmp,$r,LOCK_EX);$l=pilint($tmp);@unlink($tmp);
    return ['ok'=>($s===PI_NEW_SHA&&!empty($l['ok'])),'raw'=>$r,'sha'=>$s,'lint'=>$l];
}
function pipre():array{
    $p=pitarget();$exists=is_file($p);$old=$exists?(string)hash_file('sha256',$p):'';$cand=picandidate();
    $checks=[
        ['label'=>'Installer running from /public_html/_installers','status'=>(basename(__DIR__)==='_installers')?'PASS':'FAIL','required'=>true,'detail'=>__DIR__],
        ['label'=>'Target exists: '.PI_TARGET,'status'=>$exists?'PASS':'FAIL','required'=>true,'detail'=>$p],
        ['label'=>'Current production SHA-256 matches installed v005','status'=>($old===PI_OLD_SHA)?'PASS':'FAIL','required'=>true,'detail'=>$old],
        ['label'=>'Target folder writable','status'=>is_writable(dirname($p))?'PASS':'FAIL','required'=>true,'detail'=>dirname($p)],
        ['label'=>'Candidate SHA-256','status'=>($cand['sha']===PI_NEW_SHA)?'PASS':'FAIL','required'=>true,'detail'=>$cand['sha']],
        ['label'=>'Candidate php -l','status'=>!empty($cand['lint']['ok'])?'PASS':'FAIL','required'=>true,'detail'=>(string)$cand['lint']['output']],
    ];
    $ok=true;foreach($checks as $c)if($c['required']&&$c['status']!=='PASS')$ok=false;
    return [
        'installer'=>'install_payouts_finish_cleanup_v006','installer_version'=>PI_VER,'report_stage'=>'PRECHECK','report_generated_et'=>date('c'),
        'scope'=>[
            'changes'=>['OFFICIAL/UNOFFICIAL moved into top control row','High Point Total R## enforced for all weekly/tie labels','Team Payout grand-total amount shown as current / planned'],
            'does_not_change'=>['payout calculations','tie money allocation','payouts_helper.php','admin_payouts.php','payouts_config.json','weekly_standings.php','database','cron/scheduler','email','pick submissions']
        ],
        'result'=>['ok'=>$ok,'checks'=>$checks,'files'=>[PI_TARGET=>['path'=>$p,'sha256_before'=>$old,'expected_before_sha256'=>PI_OLD_SHA,'candidate_sha256'=>PI_NEW_SHA,'action'=>'replace']]],
        'last_installer_session'=>$_SESSION['pipv6_last']??[]
    ];
}
function piwrite(string $p,string $r):void{
    $tmp=$p.'.mrlnew_'.bin2hex(random_bytes(4));
    if(file_put_contents($tmp,$r,LOCK_EX)===false)throw new RuntimeException('Could not stage target.');
    @chmod($tmp,0644);if(!@rename($tmp,$p)){@unlink($tmp);throw new RuntimeException('Could not replace target.');}@chmod($p,0644);
}
function pipost(array $session):array{
    $p=pitarget();$exists=is_file($p);$s=$exists?(string)hash_file('sha256',$p):'';$l=$exists?pilint($p):['ok'=>false,'output'=>'Missing target.'];
    $checks=[
        ['label'=>'Installed target exists','status'=>$exists?'PASS':'FAIL','required'=>true,'detail'=>$p],
        ['label'=>'Installed SHA-256 matches v006','status'=>($s===PI_NEW_SHA)?'PASS':'FAIL','required'=>true,'detail'=>$s],
        ['label'=>'Installed php -l','status'=>!empty($l['ok'])?'PASS':'FAIL','required'=>true,'detail'=>(string)$l['output']]
    ];
    $ok=true;foreach($checks as $c)if($c['required']&&$c['status']!=='PASS')$ok=false;
    return ['installer'=>'install_payouts_finish_cleanup_v006','installer_version'=>PI_VER,'report_stage'=>'POSTCHECK','report_generated_et'=>date('c'),'result'=>['ok'=>$ok,'checks'=>$checks,'files'=>[PI_TARGET=>['path'=>$p,'sha256_after'=>$s,'expected_sha256'=>PI_NEW_SHA,'lint'=>$l]]],'last_installer_session'=>$session];
}

if(!isset($_SESSION['pipv6_csrf']))$_SESSION['pipv6_csrf']=bin2hex(random_bytes(24));
$msg='';$mc='info';
if($_SERVER['REQUEST_METHOD']==='POST'){
    $a=(string)($_POST['action']??'');
    if(!hash_equals((string)$_SESSION['pipv6_csrf'],(string)($_POST['csrf']??''))){$msg='Security token mismatch.';$mc='bad';}
    elseif($a==='apply'){
        $pre=pipre();
        if(empty($pre['result']['ok'])){$msg='Apply blocked: preflight is not fully green.';$mc='bad';}
        else{
            $p=pitarget();$backup=piroot().'/_installer_backups/install_payouts_finish_cleanup_v006_'.date('Ymd_hisA').'/'.PI_TARGET;
            try{
                if(!is_dir(dirname($backup))&&!mkdir(dirname($backup),0755,true)&&!is_dir(dirname($backup)))throw new RuntimeException('Could not create backup folder.');
                if(!copy($p,$backup))throw new RuntimeException('Backup failed.');
                if(hash_file('sha256',$backup)!==PI_OLD_SHA)throw new RuntimeException('Backup SHA mismatch.');
                $cand=picandidate();if(empty($cand['ok']))throw new RuntimeException('Candidate validation failed.');
                piwrite($p,(string)$cand['raw']);
                $session=['last_action'=>'apply','at_et'=>date('c'),'ok'=>true,'message'=>'Apply completed; running postflight.','backup'=>$backup,'automatic_rollback'=>null];
                $post=pipost($session);
                if(empty($post['result']['ok'])){@copy($backup,$p);$session['ok']=false;$session['message']='Critical postflight failed; original payouts.php restored.';$session['automatic_rollback']='restored backup';$msg=$session['message'];$mc='bad';}
                else{$session['message']='PASS — Payouts finish cleanup v006 installed and passed postflight.';$msg=$session['message'];$mc='ok';}
                $_SESSION['pipv6_last']=$session;$_SESSION['pipv6_post']=pipost($session);
            }catch(Throwable $e){
                if(isset($backup)&&is_file($backup))@copy($backup,$p);
                $session=['last_action'=>'apply','at_et'=>date('c'),'ok'=>false,'message'=>'Apply failed: '.$e->getMessage(),'backup'=>$backup??'','automatic_rollback'=>(isset($backup)&&is_file($backup))?'restored backup':'no backup available'];
                $_SESSION['pipv6_last']=$session;$_SESSION['pipv6_post']=pipost($session);$msg=$session['message'];$mc='bad';
            }
        }
    }elseif($a==='rollback'){
        $last=$_SESSION['pipv6_last']??[];$b=(string)($last['backup']??'');$ok=($b!==''&&is_file($b)&&copy($b,pitarget()));
        $session=['last_action'=>'rollback','at_et'=>date('c'),'ok'=>$ok,'message'=>$ok?'Rollback complete.':'Rollback failed: backup unavailable or copy failed.','backup'=>$b,'automatic_rollback'=>null];
        $_SESSION['pipv6_last']=$session;$_SESSION['pipv6_post']=pipost($session);$msg=$session['message'];$mc=$ok?'ok':'bad';
    }
}
$pre=pipre();$post=$_SESSION['pipv6_post']??null;
$prej=json_encode($pre,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE);
$postj=is_array($post)?json_encode($post,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE):'';
?>
